fn check_pair(amount: u64, fee: u64) {
    let gross = (amount as u128 + fee as u128 + 9_999) / 10_000;
    let debit = amount as u128 + gross - gross / 10;
    check(0, amount, fee);
    check(u64::MAX, amount, fee);
    if debit <= u64::MAX as u128 {
        let d = debit as u64;
        check(d, amount, fee);
        if d > 0 { check(d - 1, amount, fee); }
        if d < u64::MAX { check(d + 1, amount, fee); }
    }
}
fn next(state: &mut u64) -> u64 {
    *state ^= *state << 13;
    *state ^= *state >> 7;
    *state ^= *state << 17;
    *state
}
fn main() {
    let values = [0, 1, 9, 10, 9_998, 9_999, 10_000, 10_001,
                  99_990, 99_991, 100_000, u64::MAX / 2,
                  u64::MAX - 10_000, u64::MAX - 9_999,
                  u64::MAX - 1_616, u64::MAX - 1_615, u64::MAX - 1, u64::MAX];
    for amount in values { for fee in values { check_pair(amount, fee); } }
    for offset in 0..30_000u64 {
        check_pair(0, u64::MAX - offset);
        check_pair(offset, u64::MAX);
        check_pair(u64::MAX - offset, offset);
    }
    let mut state = 0x123456789abcdefu64;
    for _ in 0..200_000 {
        let amount = next(&mut state);
        let fee = next(&mut state);
        check_pair(amount, fee);
        check(next(&mut state), amount, fee);
    }
    println!("Independent exact-integer oracle: all boundary and randomized checks passed");
}
